void jerp_interrupts_array_deinit(int unit)
{
    soc_interrupt_db_t *jerp_interrupts;
    soc_interrupt_tree_t *jerp_interrupt_tree;
    int inter = 0;
    SOCDNX_INIT_FUNC_DEFS;

    
    if(NULL == SOC_CONTROL(unit)->interrupts_info) {
        SOC_EXIT;
    }

    jerp_interrupts = SOC_CONTROL(unit)->interrupts_info->interrupt_db_info;
    jerp_interrupt_tree = SOC_CONTROL(unit)->interrupts_info->interrupt_tree_info;

    for (inter = 0; inter < JERP_INT_LAST ; inter++) {
        if (jerp_interrupts[inter].statistics_count != NULL) {
            sal_free(jerp_interrupts[inter].statistics_count);
            jerp_interrupts[inter].statistics_count = NULL;
        }
        if (jerp_interrupts[inter].storm_nominal_count != NULL) {
            sal_free(jerp_interrupts[inter].storm_nominal_count);
            jerp_interrupts[inter].storm_nominal_count = NULL;
        }       
        if (jerp_interrupts[inter].storm_detection_occurrences != NULL) {
            sal_free(jerp_interrupts[inter].storm_detection_occurrences);
            jerp_interrupts[inter].storm_detection_occurrences = NULL;
        }
        if (jerp_interrupts[inter].storm_detection_start_time != NULL) {
            sal_free(jerp_interrupts[inter].storm_detection_start_time);
            jerp_interrupts[inter].storm_detection_start_time = NULL;
        }
    }

    if (jerp_interrupts != NULL) {
        sal_free(jerp_interrupts);
        SOC_CONTROL(unit)->interrupts_info->interrupt_db_info = NULL;
    }

    if (jerp_interrupt_tree != NULL) {
        sal_free(jerp_interrupt_tree);
        SOC_CONTROL(unit)->interrupts_info->interrupt_tree_info = NULL;
    }

    if(SOC_CONTROL(unit)->interrupts_info != NULL) {
        sal_free(SOC_CONTROL(unit)->interrupts_info);
        SOC_CONTROL(unit)->interrupts_info = NULL;
    }

exit:
    SOCDNX_FUNC_RETURN_VOID;
}

